  "summary": "该文件存储最新的恐惧贪婪指数数据，包含多维度评分、维度聚合、决策矩阵、极端信号、区域上下文和历史锚点等，用于决策支持。",
  "checkpoints": [
    {
      "focus": "顶层键拼写检查",
      "lines": "1-20",
      "why": "确保顶层键（如fgi_final、percentile_label等）无拼写错误，避免下游解析失败。"
    },
    {
      "focus": "scores对象键拼写与一致性",
      "lines": "14-25",
      "why": "指标代码（M1, M2等）应在整个文件中保持一致，且与statuses和extreme_signals中的引用完全匹配。"
    },
    {
      "focus": "dimensions对象键拼写",
      "lines": "27-33",
      "why": "维度名称（如momentum、sentiment）需与数据生成逻辑一致，避免聚合错误。"
    },
    {
      "focus": "decision_matrix对象键完整性",
      "lines": "34-45",
      "why": "关键决策字段（如quadrant、valuation_tier）的拼写直接影响下游策略逻辑。"
    },
    {
      "focus": "extreme_signals中指标代码有效性",
      "lines": "48-79",
      "why": "检查high和low数组中的指标代码是否均在scores中定义，防止引用空数据。"
    }
  ]
}

{
  "summary": "该文件为恐惧贪婪指数(FGI)与上证综指的历史回测报告，包含多种持有期和分组统计、IC分析、分层回测及定投结果。键名结构清晰，但需验证所有键的拼写准确性与一致性，特别是统计学术语和缩写。",
  "checkpoints": [
    {
      "focus": "所有统计学术语键名的拼写",
