        df = pd.DataFrame([{
            "date": pd.Timestamp.now().strftime("%Y-%m-%d"),
            "net_flow": 1000000.0,
        }])
        return DataSourceResult(df, DataSourceStatus.HEALTHY, self._name)", "suggestion_code": "    def fetch_industry_fund_flow(self, start_date: str, end_date: str) -> DataSourceResult:
        if not self._healthy:
            return DataSourceResult(None, DataSourceStatus.FAILED, self._name, "Mock failure")
        dates = pd.date_range(start=start_date, end=end_date, freq="B")
        df = pd.DataFrame({
            "date": dates.strftime("%Y-%m-%d"),
            "net_flow": [1000000.0] * len(dates),
